-- KS: 104 researched stops.
--
-- 102 new, 2 updating a row already in the index.
-- After running this and scripts/refresh-site.mts, /explore should read
-- 6890.
--
-- Coordinates are deliberately NOT updated on conflict: a checked position
-- must never be replaced by an unchecked one. Where the existing row came
-- from the OpenStreetMap scan and is wrong by a kilometre, delete that slug
-- first and let this insert instead.
--
-- state is deliberately NOT updated either. That is how an overwritten stop
-- in another state keeps its old state and hides — so the collision check
-- above refuses rather than relying on anyone noticing afterwards.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, timezone)
values
  ('Garden of Eden', 'garden-of-eden', 'roadside-oddities', 39.0579, -98.53515, 'Lucas', 'KS', 'Civil War veteran S.P. Dinsmoor transformed his home into a dense concrete sculpture environment filled with biblical scenes, political allegory, and handmade figures. His limestone cabin and unusual mausoleum make this one of the strongest outsider-art stops in the state.', 'open', 'https://gardenofedenlucas.org/', 'America/Chicago'),
  ('Bowl Plaza', 'bowl-plaza', 'roadside-oddities', 39.05898, -98.53836, 'Lucas', 'KS', 'Lucas turned a public restroom into a giant mosaic toilet-themed art environment, complete with sculptural plumbing references and colorful found-object details. It is functional civic infrastructure deliberately built as an absurd roadside attraction.', 'open', 'https://www.travelks.com/listing/bowl-plaza/15640/', 'America/Chicago'),
  ('Grassroots Art Center', 'grassroots-art-center', 'roadside-oddities', 39.05756, -98.53832, 'Lucas', 'KS', 'This museum preserves Kansas folk, self-taught, and grassroots art made by people working outside conventional fine-art systems. The collection is especially useful as a gateway to the many eccentric art environments scattered across north-central Kansas.', 'open', 'https://www.grassrootsart.net/', 'America/Chicago'),
  ('Florence Deeble Rock Garden', 'florence-deeble-rock-garden', 'roadside-oddities', 39.05852, -98.53642, 'Lucas', 'KS', 'Florence Deeble spent decades building miniature landscapes and travel memories from concrete, stone, and found material around her home. The result is a compact folk-art environment of mountains, villages, monuments, and personal geography.', 'open', 'https://www.grassrootsart.net/', 'America/Chicago'),
  ('World''s Largest Collection of the World''s Smallest Versions of the World''s Largest Things', 'world-s-largest-collection-of-the-world-s-smallest-versions-of-the-world-s-large', 'museums', 39.05759, -98.53791, 'Lucas', 'KS', 'Artist Erika Nelson created miniature versions of oversized roadside attractions from around the country, turning roadside gigantism back into tiny objects. The tongue-twisting collection functions as both museum and affectionate parody of American road-trip culture.', 'limited', 'https://www.worldslargestthings.com/', 'America/Chicago'),
  ('World''s Largest Souvenir Travel Plate', 'worlds-largest-souvenir-travel-plate', 'roadside-oddities', 39.05769, -98.52819, 'Lucas', 'KS', 'A giant roadside travel plate welcomes visitors on the edge of Lucas and celebrates the souvenir plates once collected on cross-country trips. Its exaggerated scale fits the town''s larger tradition of deliberately strange public art.', 'roadside', 'https://www.travelks.com/listing/worlds-largest-travel-plate/18782/', 'America/Chicago'),
  ('M.T. Liggett Art Environment', 'mt-liggett-art-environment', 'roadside-oddities', 37.58759, -99.48013, 'Mullinville', 'KS', 'M.T. Liggett filled his roadside property with whirling metal sculptures, political caricatures, signs, and kinetic scrap-metal figures. The preserved environment remains one of Kansas''s most confrontational and instantly recognizable folk-art landscapes.', 'open', 'https://mtliggettartenvironment.org/', 'America/Chicago'),
  ('Big Brutus', 'big-brutus', 'weird-history', 37.27348, -94.9382, 'West Mineral', 'KS', 'This enormous electric mining shovel once stripped overburden from southeast Kansas coal fields and now stands preserved as a museum centerpiece. Its scale is difficult to understand until standing beneath the 16-story machine.', 'open', 'https://www.bigbrutus.org/', 'America/Chicago'),
  ('Mushroom Rock State Park', 'mushroom-rock-state-park', 'roadside-oddities', 38.72613, -98.02972, 'Marquette', 'KS', 'Wind and water eroded sandstone into oversized mushroom-shaped rocks balanced on narrow stems. The tiny state park is a concentrated collection of geological forms that look deliberately sculpted despite being natural.', 'open', 'https://ksoutdoors.gov/about-kdwp/where-we-work/state-parks/mushroom-rock', 'America/Chicago'),
  ('Rock City', 'rock-city', 'roadside-oddities', 39.0875, -97.73167, 'Minneapolis', 'KS', 'More than 200 nearly spherical sandstone concretions cluster across a small landscape outside Minneapolis. Some are several meters across, creating a field of giant stone balls unlike most other Kansas geology.', 'open', 'https://www.rockcitypark.com/', 'America/Chicago'),
  ('Monument Rocks', 'monument-rocks', 'roadside-oddities', 38.79326, -100.76268, 'Oakley', 'KS', 'Towering chalk formations rise abruptly from the western Kansas plains and preserve evidence of the ancient inland sea that once covered the region. The formations are on private land opened to visitors, so access is a privilege and poor road conditions can close the route.', 'limited', 'https://www.visitoakleyks.com/monument-rocks', 'America/Chicago'),
  ('Little Jerusalem Badlands State Park', 'little-jerusalem-badlands-state-park', 'roadside-oddities', 38.80281, -100.9282, 'Oakley', 'KS', 'White Niobrara chalk cliffs, spires, and narrow formations form a badlands landscape that looks dramatically different from the surrounding prairie. Visitors can use public overlooks and trails, while guided hikes reach more sensitive areas.', 'open', 'https://ksoutdoors.gov/about-kdwp/where-we-work/state-parks/little-jerusalem', 'America/Chicago'),
  ('Castle Rock Badlands', 'castle-rock-badlands', 'roadside-oddities', 38.86116, -100.16974, 'Quinter', 'KS', 'Chalk spires and eroded badlands surround the isolated Castle Rock formation in western Kansas. The site is reached across private ranch roads, so visitors should only go in dry conditions and respect posted access rules.', 'limited', 'https://www.travelks.com/things-to-do/parks-and-nature/scenic-areas/castle-rock/', 'America/Chicago'),
  ('Arikaree Breaks', 'arikaree-breaks', 'roadside-oddities', 39.91062, -101.78619, 'St. Francis', 'KS', 'Deep ravines and rugged loess formations cut through the far northwest corner of Kansas, producing terrain more often associated with neighboring states. Most land is private, but the breaks can be viewed from lawful public gravel roads.', 'roadside', 'https://www.travelks.com/things-to-do/parks-and-nature/scenic-areas/arikaree-breaks/', 'America/Chicago'),
  ('Big Basin Prairie Preserve and St. Jacob''s Well', 'big-basin-prairie-preserve-and-st-jacobs-well', 'roadside-oddities', 37.24037, -99.98186, 'Ashland', 'KS', 'A broad natural sink and a smaller water-filled sinkhole known as St. Jacob''s Well interrupt the prairie south of Dodge City. Local folklore and the unusual karst terrain make the preserve more than a normal scenic stop, but road and weather conditions can affect access.', 'limited', 'https://www.travelks.com/', 'America/Chicago'),
  ('Geographic Center of the Contiguous United States', 'geographic-center-of-the-contiguous-united-states', 'roadside-oddities', 39.82816, -98.56956, 'Lebanon', 'KS', 'A stone monument and tiny chapel mark the traditional geographic center of the lower 48 states. The exact mathematical definition can vary, but this rural Kansas landmark became the enduring public symbol of the nation''s middle.', 'open', 'https://www.travelks.com/', 'America/Chicago'),
  ('Mount Sunflower', 'mount-sunflower', 'roadside-oddities', 39.02194, -102.03722, 'Weskan', 'KS', 'Kansas''s highest natural point is not a mountain but a subtle rise on private ranchland beside the Colorado line. The owners traditionally welcome respectful visitors, who find a sign, register, and whimsical summit markers rather than an alpine peak.', 'limited', 'https://www.travelks.com/listing/mount-sunflower/21305/', 'America/Denver'),
  ('Kansas-Colorado-Oklahoma Tri-State Marker', 'kansas-colorado-oklahoma-tri-state-marker', 'roadside-oddities', 36.99323, -102.04204, 'Elkhart', 'KS', 'A survey marker identifies the point where Kansas, Colorado, and Oklahoma meet. Reaching it requires rural roads near the edge of all three states, making the stop as much about standing on an abstract boundary as seeing a monument.', 'roadside', 'https://www.ci.elkhart.ks.us/175/Tri-State-Marker', 'America/Chicago'),
  ('Four-State Lookout', 'four-state-lookout', 'roadside-oddities', 39.97975, -95.29953, 'White Cloud', 'KS', 'A hilltop overlook above White Cloud is promoted for views across Kansas, Missouri, Nebraska, and, under clear conditions, toward Iowa. It is a simple public viewpoint whose appeal comes from the unusual multi-state geography.', 'open', 'https://www.travelks.com/', 'America/Chicago'),
  ('Giant Van Gogh ''Three Sunflowers in a Vase''', 'giant-van-gogh-three-sunflowers-in-a-vase', 'roadside-oddities', 39.33794, -101.70482, 'Goodland', 'KS', 'A gigantic reproduction of Van Gogh''s sunflower painting stands on an approximately 80-foot easel beside the highway. It was built as part of artist Cameron Cross''s international Big Easel Project and has become Goodland''s signature roadside landmark.', 'open', 'https://www.travelks.com/', 'America/Denver'),
  ('High Plains Museum', 'high-plains-museum', 'museums', 39.3411, -101.70558, 'Goodland', 'KS', 'Goodland''s city museum mixes regional artifacts with exhibits tied to inventions, transportation, and the unusual history of the High Plains. Its location only a short walk from the giant Van Gogh makes it a useful second OddWay stop rather than a generic local museum.', 'open', 'https://www.cityofgoodland.org/', 'America/Denver'),
  ('Fick Fossil and History Museum', 'fick-fossil-and-history-museum', 'museums', 39.12801, -100.86162, 'Oakley', 'KS', 'The Fick Museum combines western Kansas fossils with Vi Fick''s eccentric folk art made from shark teeth, fish bones, shells, wax, and other materials. Large marine fossils are a reminder that this dry region once lay beneath the Western Interior Seaway.', 'open', 'https://www.visitoakleyks.com/fick-fossil-history-museum', 'America/Chicago'),
  ('Buffalo Bill Cultural Center and Giant Bronze', 'buffalo-bill-cultural-center-and-giant-bronze', 'roadside-oddities', 39.12682, -100.86948, 'Oakley', 'KS', 'A twice-life-size bronze depicts Buffalo Bill Cody on horseback pursuing a buffalo near the place where local tradition says he earned his famous nickname in an 1868 hunting contest. The outdoor sculpture is accessible even when the visitor center is closed.', 'open', 'https://www.visitoakleyks.com/buffalo-bill-cultural-center', 'America/Chicago'),
  ('Dorothy''s House and Land of Oz', 'dorothys-house-and-land-of-oz', 'museums', 37.03436, -100.91041, 'Liberal', 'KS', 'Liberal built a replica of Dorothy Gale''s Kansas home and an indoor Yellow Brick Road attraction around the state''s connection to The Wizard of Oz. Guided visits lean heavily into handmade sets, memorabilia, and roadside-theater charm.', 'open', 'https://visitliberal.com/', 'America/Chicago'),
  ('Mid-America Air Museum', 'mid-america-air-museum', 'museums', 37.03884, -100.95141, 'Liberal', 'KS', 'This city-operated museum holds one of the country''s larger collections of historic aircraft, ranging from military machines to unusual civilian designs. The dense hangar presentation makes it a strong stop for aviation and mechanical-history travelers.', 'open', 'https://liberalairmuseum.com/', 'America/Chicago'),
  ('International Pancake Day Hall of Fame', 'international-pancake-day-hall-of-fame', 'museums', 37.04132, -100.924, 'Liberal', 'KS', 'Liberal''s long-running pancake race against Olney, England, has its own museum filled with racing memorabilia, frying pans, photographs, costumes, and international gifts. Outside the annual event it is generally visited by appointment.', 'limited', 'https://visitliberal.com/international-pancake-day/', 'America/Chicago'),
  ('World''s Largest Czech Egg', 'world-s-largest-czech-egg', 'roadside-oddities', 38.82412, -98.47275, 'Wilson', 'KS', 'A 22-foot decorated kraslice stands in Wilson as a giant tribute to the community''s Czech heritage. The colorful egg combines immigrant tradition with the oversized-object logic of a classic roadside attraction.', 'open', 'https://www.travelks.com/', 'America/Chicago'),
  ('Atlas Ad Astra Missile Silo', 'atlas-ad-astra-missile-silo', 'weird-history', 38.83378, -98.43086, 'Wilson', 'KS', 'A decommissioned Atlas F intercontinental ballistic missile complex has been repurposed for tours, camping, and an evolving underground adventure project. Visitors can see Cold War infrastructure that was designed to launch a nuclear missile, but advance booking is required.', 'limited', 'https://www.atlasadastra.com/', 'America/Chicago'),
  ('Big Well Museum', 'big-well-museum', 'weird-history', 37.60341, -99.29444, 'Greensburg', 'KS', 'The museum allows visitors to descend into the enormous hand-dug municipal well completed in 1888. Exhibits also document Greensburg''s destruction in the 2007 tornado and the community''s reconstruction.', 'open', 'https://www.bigwell.org/', 'America/Chicago'),
  ('World''s Largest Cow Hairball', 'worlds-largest-cow-hairball', 'museums', 37.96027, -100.87081, 'Garden City', 'KS', 'The Finney County Historical Museum displays a huge trichobezoar removed from a cow''s stomach at a local packing plant. Once far heavier when wet, the dried hairball remains an unusually tactile museum object and one of Kansas''s strangest documented artifacts.', 'open', 'https://finneycounty.org/170/Historical-Museum', 'America/Chicago'),
  ('Sternberg Museum of Natural History', 'sternberg-museum-of-natural-history', 'museums', 38.89733, -99.31582, 'Hays', 'KS', 'The Sternberg focuses on fossils and natural history from the central plains, including dramatic marine reptiles from the ancient inland sea. Its famous ''fish-within-a-fish'' fossil and extensive Cretaceous collection give it a strong prehistoric OddWay hook.', 'open', 'https://sternberg.fhsu.edu/', 'America/Chicago'),
  ('Fort Hays State Historic Site', 'fort-hays-state-historic-site', 'weird-history', 38.86198, -99.34314, 'Hays', 'KS', 'Four surviving buildings preserve part of the frontier military post associated with Buffalo Soldiers, railroad expansion, and figures such as Custer, Hickok, and Cody. The open landscape makes the fort''s isolation and military role easier to understand than a conventional indoor museum.', 'open', 'https://www.kansashistory.gov/fort_hays', 'America/Chicago'),
  ('Strataca', 'strataca', 'weird-history', 38.0437, -97.86755, 'Hutchinson', 'KS', 'Visitors descend about 650 feet into a working-area salt formation more than 275 million years old. Underground galleries combine mining history, geology, preserved film materials, and rides through former mine passages.', 'open', 'https://underkansas.org/', 'America/Chicago'),
  ('Cosmosphere', 'cosmosphere', 'weird-history', 38.06561, -97.92138, 'Hutchinson', 'KS', 'The Cosmosphere houses major American and Soviet spaceflight artifacts, including flown spacecraft and Cold War-era hardware. Its concentration of genuine space objects makes it far more than a general science museum for OddWay purposes.', 'open', 'https://cosmo.org/', 'America/Chicago'),
  ('Little House on the Prairie Museum', 'little-house-on-the-prairie-museum', 'weird-history', 37.12487, -95.83678, 'Independence', 'KS', 'The museum complex stands near the Kansas homestead associated with Laura Ingalls Wilder''s family and includes a reconstructed cabin and period buildings. It ties a globally known frontier story to a specific rural Kansas landscape.', 'limited', 'https://littlehouseontheprairiemuseum.com/', 'America/Chicago'),
  ('Norman No. 1 Oil Well', 'norman-no-1-oil-well', 'weird-history', 37.4125, -95.62778, 'Neodesha', 'KS', 'A reconstructed wooden derrick marks the site of the 1892 Norman No. 1, widely recognized as the first commercially successful oil well in the Mid-Continent field. The small site represents the beginning of an industry that transformed Kansas and neighboring states.', 'open', 'https://www.kansashistory.gov/', 'America/Chicago'),
  ('Dalton Gang Hideout and Escape Tunnel', 'dalton-gang-hideout-and-escape-tunnel', 'weird-history', 37.28096, -100.3371, 'Meade', 'KS', 'A house linked to relatives of the Dalton brothers became famous for a concealed tunnel running from the home toward a barn. Whether every outlaw story attached to it is literal or embellished, the preserved tunnel and Dalton connection make it an unusually physical piece of western folklore.', 'open', 'http://www.oldmeadecounty.com/hideout.htm', 'America/Chicago'),
  ('Stockade Museum', 'stockade-museum', 'weird-history', 37.27562, -98.58168, 'Medicine Lodge', 'KS', 'A reconstructed stockade and museum interpret Medicine Lodge''s frontier period, regional conflict, settlement, and treaty-era history. The enclosed timber structure gives the site a distinctive physical character compared with a standard county museum.', 'open', 'https://www.medicinelodgestockade.org/', 'America/Chicago'),
  ('Carry Nation Home', 'carry-nation-home', 'weird-history', 37.27555, -98.58179, 'Medicine Lodge', 'KS', 'The preserved home of temperance activist Carry A. Nation sits beside the Stockade Museum complex. Nation became nationally famous for smashing saloons with a hatchet, giving the modest house an unusually vivid connection to American protest history.', 'open', 'https://www.medicinelodgestockade.org/', 'America/Chicago'),
  ('Boyer Museum of Animated Carvings', 'boyer-museum-of-animated-carvings', 'roadside-oddities', 39.82867, -97.63075, 'Belleville', 'KS', 'Paul Boyer''s hand-built wooden automata move through elaborate mechanical scenes powered by gears, cams, wire, and motors. The museum preserves decades of one-person engineering and folk art rather than mass-produced displays.', 'limited', 'https://www.travelks.com/', 'America/Chicago'),
  ('Pony Express Barn Museum', 'pony-express-barn-museum', 'weird-history', 39.84166, -96.64802, 'Marysville', 'KS', 'An original 1859 stone barn served as a Pony Express home station where riders and horses could be changed. The museum preserves one of the few substantial surviving structures directly connected to the short-lived mail service.', 'open', 'https://www.visitmarysvilleks.org/', 'America/Chicago'),
  ('Hollenberg Pony Express Station', 'hollenberg-pony-express-station', 'weird-history', 39.90091, -96.84381, 'Hanover', 'KS', 'Built in the late 1850s, Hollenberg Station served emigrant trails and later the Pony Express without being moved from its original site. Its survival makes it one of Kansas''s strongest physical links to overland migration and the famous 18-month mail route.', 'limited', 'https://www.kansashistory.gov/hollenberg', 'America/Chicago'),
  ('Pawnee Indian Museum State Historic Site', 'pawnee-indian-museum-state-historic-site', 'weird-history', 39.90785, -97.861, 'Republic', 'KS', 'The museum protects the excavated floor of a large Pawnee earth lodge from a village occupied in the late 1700s and early 1800s. Archaeology, a rare sacred bundle, and visible lodge depressions make the landscape itself part of the interpretation.', 'limited', 'https://www.kansashistory.gov/pawnee_indian', 'America/Chicago'),
  ('Kansas Barbed Wire Museum', 'kansas-barbed-wire-museum', 'museums', 38.52468, -99.31162, 'La Crosse', 'KS', 'Thousands of varieties of barbed wire and fencing tools document how many different ways inventors tried to control the open plains. A subject that sounds mundane becomes a surprisingly dense museum of patents, violence, ranching, and material culture.', 'limited', 'https://barbedwiremuseum.com/', 'America/Chicago'),
  ('They Also Ran Gallery', 'they-also-ran-gallery', 'museums', 39.8294, -99.88927, 'Norton', 'KS', 'This unusual political gallery focuses not on presidents but on major-party presidential nominees who lost. Portraits and biographies turn American history toward the people who came close to the White House and then largely disappeared from popular memory.', 'limited', 'http://www.theyalsoran.com/', 'America/Chicago'),
  ('Moline Swinging Bridge', 'moline-swinging-bridge', 'roadside-oddities', 37.36578, -96.30433, 'Moline', 'KS', 'A narrow pedestrian suspension bridge crosses Wildcat Creek and is locally described as Kansas''s oldest swinging bridge. Its movement underfoot and small-town park setting give it the kind of simple physical oddity that works well as a route stop.', 'open', 'https://www.travelks.com/', 'America/Chicago'),
  ('OZ Museum', 'oz-museum', 'museums', 39.20122, -96.3053, 'Wamego', 'KS', 'Wamego''s museum gathers Wizard of Oz books, film material, replicas, collectibles, and themed environments into a dedicated Oz attraction. Kansas''s fictional role in the story is turned into a substantial real-world roadside destination.', 'open', 'https://ozmuseum.com/', 'America/Chicago'),
  ('Original Pizza Hut Museum', 'original-pizza-hut-museum', 'museums', 37.72103, -97.28654, 'Wichita', 'KS', 'The tiny original Pizza Hut building was moved onto Wichita State University''s campus and turned into a museum about the global restaurant chain that began there in 1958. It is an unusually small birthplace for an enormous commercial brand.', 'open', 'https://www.wichita.edu/about/wsunews/pizza_hut_museum.php', 'America/Chicago'),
  ('Museum of World Treasures', 'museum-of-world-treasures', 'museums', 37.68705, -97.32789, 'Wichita', 'KS', 'This eclectic museum deliberately mixes fossils, ancient objects, military history, mummies, and other artifacts rather than focusing on a single period. The breadth and cabinet-of-curiosities feel make it a stronger OddWay fit than a conventional history museum.', 'open', 'https://worldtreasures.org/', 'America/Chicago'),
  ('Kansas Aviation Museum', 'kansas-aviation-museum', 'weird-history', 37.63217, -97.27372, 'Wichita', 'KS', 'The museum occupies Wichita''s former Art Deco municipal airport terminal and surrounds it with aircraft tied to the city''s aviation industry. Visitors can explore both the historic terminal architecture and a collection of unusual airframes.', 'open', 'https://kansasaviationmuseum.org/', 'America/Chicago'),
  ('Keeper of the Plains', 'keeper-of-the-plains', 'weird-history', 37.69138, -97.34968, 'Wichita', 'KS', 'Blackbear Bosin''s 44-foot steel figure stands at the confluence of the Arkansas and Little Arkansas rivers. The surrounding plaza, footbridges, and scheduled fire pots make the monument one of Kansas''s most distinctive large-scale public artworks.', 'open', 'https://www.wichita.gov/', 'America/Chicago'),
  ('Old Cowtown Museum', 'old-cowtown-museum', 'museums', 37.69379, -97.36225, 'Wichita', 'KS', 'A collection of historic and reconstructed buildings creates a walkable 19th-century townscape covering frontier and early Wichita life. Its saloons, businesses, streets, and demonstrations offer a more immersive old-west environment than a display-case museum.', 'open', 'https://www.oldcowtown.org/', 'America/Chicago'),
  ('Combat Air Museum', 'combat-air-museum', 'weird-history', 38.94671, -95.68446, 'Topeka', 'KS', 'Two hangars at Forbes Field hold dozens of military aircraft, helicopters, engines, missiles, and aviation artifacts. The volunteer-run collection spans early flight through Cold War jets and gives visitors unusually close access to large machines.', 'open', 'https://combatairmuseum.org/', 'America/Chicago'),
  ('Brown v. Board of Education National Historical Park', 'brown-v-board-of-education-national-historical-park', 'weird-history', 39.03788, -95.67614, 'Topeka', 'KS', 'The National Park Service preserves the former Monroe Elementary School, one of the segregated schools directly connected to the landmark Supreme Court case. The classrooms and exhibits make the legal history tangible at the place where part of it happened.', 'open', 'https://www.nps.gov/brvb/', 'America/Chicago'),
  ('Rochester Cemetery — ''Albino Lady'' Folklore', 'rochester-cemetery-albino-lady-folklore', 'folklore', 39.10435, -95.67988, 'Topeka', 'KS', 'Rochester Cemetery is attached to a long-running Topeka legend about an ''Albino Lady'' said to appear among the graves. Treat the story as local folklore rather than fact, visit only during lawful cemetery hours, and do not disturb graves or residents nearby.', 'limited', 'https://www.visittopeka.com/', 'America/Chicago'),
  ('Sallie House', 'sallie-house', 'haunted', 39.56659, -95.11495, 'Atchison', 'KS', 'The 19th-century house is the center of Atchison''s best-known ghost story, commonly associated with a child called Sallie and decades of paranormal reports. It operates as a bookable attraction, so entry should only be through official tours or reservations.', 'limited', 'https://visitatchison.com/highlight/sallie-house', 'America/Chicago'),
  ('McInteer Villa', 'mcinteer-villa', 'haunted', 39.56334, -95.13351, 'Atchison', 'KS', 'This imposing 1889 brick mansion is both a historic home and one of Atchison''s established paranormal-tour locations. Stories of apparitions and unexplained activity are part of the property''s visitor experience, but should be understood as reported lore rather than verified events.', 'limited', 'https://visitatchison.com/', 'America/Chicago'),
  ('Amelia Earhart Birthplace Museum', 'amelia-earhart-birthplace-museum', 'weird-history', 39.56375, -95.11448, 'Atchison', 'KS', 'The Gothic Revival house overlooking the Missouri River is the birthplace of pioneering aviator Amelia Earhart. Period rooms and personal material tie one of aviation''s most enduring mysteries to a very specific Kansas home.', 'open', 'https://www.ameliaearhartmuseum.org/', 'America/Chicago'),
  ('Amelia Earhart Hangar Museum', 'amelia-earhart-hangar-museum', 'weird-history', 39.56846, -95.17826, 'Atchison', 'KS', 'A modern museum at Amelia Earhart Airport centers on Muriel, the world''s last remaining Lockheed Electra 10-E of the same model Earhart flew on her final journey. Interactive exhibits explore her life, aircraft, navigation, and disappearance.', 'open', 'https://ameliaearharthangarmuseum.org/', 'America/Chicago'),
  ('Mount Vernon Cemetery', 'mount-vernon-cemetery', 'weird-history', 39.5416, -95.1425, 'Atchison', 'KS', 'This historic cemetery contains prominent Atchison burials and sits near the giant Amelia Earhart earthwork portrait visible from above. It is a legitimate historic destination, but visitors should follow cemetery hours and treat gravesites respectfully.', 'limited', 'https://visitatchison.com/', 'America/Chicago'),
  ('Moon Marble Company', 'moon-marble-company', 'museums', 39.05921, -94.8769, 'Bonner Springs', 'KS', 'Moon Marble combines a toy store with live demonstrations of traditional handmade glass marbles and an enormous assortment of unusual games and toys. Watching molten glass become a finished marble gives the stop a craft-process hook beyond normal retail.', 'open', 'https://moonmarble.com/', 'America/Chicago'),
  ('National Agricultural Center and Hall of Fame', 'national-agricultural-center-and-hall-of-fame', 'museums', 39.10817, -94.87368, 'Bonner Springs', 'KS', 'A large museum campus preserves historic farm machinery, rural buildings, agricultural technology, and the National Agricultural Hall of Fame. The scale and variety of obsolete machines make it a useful stop for industrial and mechanical oddities.', 'limited', 'https://aghalloffame.com/', 'America/Chicago'),
  ('Baxter Springs Heritage Center and Museum', 'baxter-springs-heritage-center-and-museum', 'weird-history', 37.02804, -94.73335, 'Baxter Springs', 'KS', 'Baxter Springs combines Route 66, mining, Civil War, and frontier history in a town that repeatedly sat on important transportation routes. The museum is a strong context stop before visiting the town''s surviving Route 66 structures.', 'open', 'https://baxterspringsmuseum.org/', 'America/Chicago'),
  ('Baxter Springs 1930 Phillips 66 Station', 'baxter-springs-1930-phillips-66-station', 'roadside-oddities', 37.02593, -94.7348, 'Baxter Springs', 'KS', 'A restored cottage-style Phillips 66 station now serves as a Route 66 visitor center. The tiny station preserves the look of early automobile travel on the Kansas segment of the Mother Road.', 'open', 'https://www.nps.gov/places/phillips-66-service-station-baxter-springs.htm', 'America/Chicago'),
  ('Rainbow Bridge', 'rainbow-bridge', 'roadside-oddities', 37.07352, -94.74083, 'Riverton', 'KS', 'This concrete Marsh arch bridge carried old Route 66 over Brush Creek and is the last surviving bridge of its type on the historic highway in Kansas. Its compact scale and distinctive white arches make it an easy roadside architecture stop.', 'roadside', 'https://www.travelks.com/', 'America/Chicago'),
  ('Old Riverton Store', 'old-riverton-store', 'roadside-oddities', 37.07494, -94.70279, 'Riverton', 'KS', 'The 1925 general store has served generations of travelers and remains one of the most authentic operating businesses on Kansas Route 66. Its groceries, deli, old building fabric, and road history give it more substance than a recreated nostalgia stop.', 'open', 'https://www.eislerbros.com/', 'America/Chicago'),
  ('Cars on the Route', 'cars-on-the-route', 'roadside-oddities', 37.08037, -94.6389, 'Galena', 'KS', 'A restored Kan-O-Tex service station displays the rusty boom truck that helped inspire Tow Mater during research for Pixar''s Cars. The station links real Route 66 history with a modern pop-culture version of the road.', 'open', 'https://www.travelks.com/', 'America/Chicago'),
  ('Gearhead Curios', 'gearhead-curios', 'roadside-oddities', 37.07553, -94.6393, 'Galena', 'KS', 'A restored 1939 filling station has been turned into a Route 66 curiosity stop filled with automotive memorabilia, art, and roadside installations. Its giant gearhead figure and preserved station architecture make it a distinct Galena stop from Cars on the Route.', 'open', 'https://gearheadcurios.com/', 'America/Chicago'),
  ('Brown Mansion', 'brown-mansion', 'roadside-oddities', 37.01995, -95.61445, 'Coffeyville', 'KS', 'Oil businessman W.P. Brown built this elaborate early-1900s mansion with ornate interiors and unusually advanced systems for its era. Local ghost stories have accumulated around the property, but its documented architecture and history are the primary reasons to visit.', 'limited', 'https://www.coffeyville.com/', 'America/Chicago'),
  ('National Orphan Train Complex', 'national-orphan-train-complex', 'weird-history', 39.57461, -97.6615, 'Concordia', 'KS', 'This museum documents the orphan-train movement that relocated tens of thousands of children from eastern cities to communities across the country. A restored Union Pacific depot and personal stories make a difficult, often complicated social history concrete.', 'open', 'https://orphantraindepot.org/', 'America/Chicago'),
  ('Camp Concordia POW Camp Site', 'camp-concordia-pow-camp-site', 'weird-history', 39.61167, -97.64028, 'Concordia', 'KS', 'The remains and museum work at Camp Concordia preserve the site of a World War II prisoner-of-war camp that held thousands of German soldiers. Surviving structures and markers sit on the former camp landscape north of town; check current tour and access information before visiting.', 'limited', 'https://www.travelks.com/', 'America/Chicago'),
  ('Boot Hill Museum', 'boot-hill-museum', 'weird-history', 37.75351, -100.02218, 'Dodge City', 'KS', 'Boot Hill interprets Dodge City''s cattle-town and gunfighter era with historic objects, reconstructed streetscapes, and the mythology that grew around the town. It deliberately occupies the line between documented frontier history and the larger-than-life western image.', 'open', 'https://boothill.org/', 'America/Chicago'),
  ('Santa Fe Trail Ruts', 'santa-fe-trail-ruts', 'weird-history', 37.79194, -100.19694, 'Dodge City', 'KS', 'Deep parallel depressions west of Dodge City preserve wagon traffic from the Santa Fe Trail in the actual prairie surface. Seeing the route physically worn into the ground is more immediate than a marker describing where a trail once passed.', 'open', 'https://www.nps.gov/', 'America/Chicago'),
  ('Mueller-Schmidt House — Home of Stone', 'mueller-schmidt-house-home-of-stone', 'roadside-oddities', 37.75551, -100.01554, 'Dodge City', 'KS', 'Built from native limestone in the 1880s, the Mueller-Schmidt House survives as one of Dodge City''s most substantial early residences. Its preserved rooms offer a quieter, more authentic counterpoint to the town''s saloon-and-gunfighter mythology.', 'limited', 'https://www.visitdodgecity.org/', 'America/Chicago'),
  ('Ellinwood Underground Tunnels', 'ellinwood-underground-tunnels', 'weird-history', 38.35377, -98.58082, 'Ellinwood', 'KS', 'Passages beneath downtown Ellinwood preserve remnants of underground storefronts, storage spaces, bath facilities, and later Prohibition-era stories. Tours are scheduled rather than freely accessible, and some sections remain beneath active private buildings.', 'limited', 'https://www.ellinwoodchamber.com/ellinwood-underground-tunnels', 'America/Chicago'),
  ('Historic Wolf Hotel', 'historic-wolf-hotel', 'haunted', 38.35377, -98.58082, 'Ellinwood', 'KS', 'The restored 1894 Wolf Hotel is a working lodging and event property connected with Ellinwood''s underground tunnel network. It also markets paranormal and history experiences, so ghost claims should be treated as part of the property''s lore rather than established fact.', 'limited', 'https://historicwolfhotel.com/', 'America/Chicago'),
  ('M65 Atomic Cannon — Junction City', 'm65-atomic-cannon-junction-city', 'weird-history', 39.03813, -96.76299, 'Junction City', 'KS', 'A massive M65 ''Atomic Annie'' artillery piece is displayed near Fort Riley, representing the brief Cold War period when nuclear shells were designed for battlefield cannon. Its sheer size and unsettling purpose make it an unusually stark military roadside artifact.', 'roadside', 'https://home.army.mil/riley/', 'America/Chicago'),
  ('First Territorial Capitol State Historic Site', 'first-territorial-capitol-state-historic-site', 'weird-history', 39.08472, -96.76167, 'Fort Riley', 'KS', 'Kansas''s first territorial legislature briefly met in this limestone building in 1855 amid the proslavery and antislavery conflict that became Bleeding Kansas. The site is inside the Fort Riley area, so visitors should review current base-entry requirements before going.', 'limited', 'https://www.kansashistory.gov/first_territorial_capitol', 'America/Chicago'),
  ('Buffalo Soldier Monument', 'buffalo-soldier-monument', 'weird-history', 39.34597, -94.91924, 'Fort Leavenworth', 'KS', 'A large bronze cavalryman and surrounding memorial elements honor the Black soldiers of the 9th and 10th Cavalry and related units. Because the monument is on an active military installation, visitors without military credentials must follow Fort Leavenworth''s current entry procedures.', 'limited', 'https://home.army.mil/leavenworth/', 'America/Chicago'),
  ('Quindaro Ruins Overlook', 'quindaro-ruins-overlook', 'weird-history', 39.15146, -94.65913, 'Kansas City', 'KS', 'The overlook faces the wooded archaeological remains of Quindaro, a Free-State river town tied to antislavery activity and the Underground Railroad. Much of the former townsite is not a normal walk-through attraction, making the public overlook the appropriate routable stop.', 'open', 'https://www.nps.gov/places/quindaro-townsite.htm', 'America/Chicago'),
  ('Sauer Castle', 'sauer-castle', 'haunted', 39.06806, -94.63389, 'Kansas City', 'KS', 'This 1870s Italianate mansion has accumulated generations of ghost stories, family legends, and local fascination. It remains private property, so OddWay visitors should view it only from lawful public areas and never enter the grounds without permission.', 'roadside', 'https://www.kansascityks.com/', 'America/Chicago'),
  ('Museum of Odd', 'museum-of-odd', 'museums', 38.96509, -95.23094, 'Lawrence', 'KS', 'A private home houses Randy Walker''s dense personal collection of sock monkeys, celebrity oddments, folk creations, unusual biological objects, and other deliberately strange material. Visits are by appointment, making it a true hosted curiosity collection rather than a walk-in museum.', 'limited', 'https://www.atlasobscura.com/places/museum-of-odd', 'America/Chicago'),
  ('The Eldridge Hotel — Haunted Lawrence Lore', 'the-eldridge-hotel-haunted-lawrence-lore', 'haunted', 38.97108, -95.23631, 'Lawrence', 'KS', 'The Eldridge stands on a site repeatedly tied to Lawrence''s violent Bleeding Kansas and Civil War-era history, and later generations attached ghost stories to the hotel. The haunting is folklore, but the building''s documented destruction and rebuilding give the stories a real historical setting.', 'open', 'https://www.explorelawrence.com/', 'America/Chicago'),
  ('Stull Cemetery — ''Gateway to Hell'' Folklore', 'stull-cemetery-gateway-to-hell-folklore', 'folklore', 38.97142, -95.45462, 'Stull', 'KS', 'Stull Cemetery became nationally notorious through late-20th-century legends claiming the site was a supernatural gateway. Those claims are folklore, not established fact; this is an active cemetery and visitors must obey posted rules, avoid nighttime trespassing, and treat burials respectfully.', 'limited', 'https://www.atlasobscura.com/places/stull-cemetery', 'America/Chicago'),
  ('John Brown Museum State Historic Site', 'john-brown-museum-state-historic-site', 'weird-history', 38.49884, -94.95957, 'Osawatomie', 'KS', 'The preserved Adair cabin is associated with abolitionist John Brown and the violent struggle over whether Kansas would enter the Union as a free or slave state. The small museum sits directly within the landscape of Bleeding Kansas rather than treating it as distant history.', 'open', 'https://www.kansashistory.gov/john_brown', 'America/Chicago'),
  ('Marais des Cygnes Massacre State Historic Site', 'marais-des-cygnes-massacre-state-historic-site', 'weird-history', 38.28157, -94.62091, 'Trading Post', 'KS', 'In 1858 proslavery men captured Free-State settlers here and shot them in a ravine, killing five. The preserved rural site contains markers and interpretation at the location of one of the final major violent episodes of Bleeding Kansas.', 'open', 'https://www.kansashistory.gov/marais_des_cygnes', 'America/Chicago'),
  ('Mine Creek Battlefield State Historic Site', 'mine-creek-battlefield-state-historic-site', 'weird-history', 38.135, -94.72444, 'Pleasanton', 'KS', 'The 1864 Battle of Mine Creek was one of the largest cavalry engagements of the Civil War and unfolded across this preserved landscape. Trails and exhibits let visitors follow the terrain where a retreating Confederate army collided with pursuing Union cavalry.', 'open', 'https://www.kansashistory.gov/mine_creek', 'America/Chicago'),
  ('Constitution Hall State Historic Site', 'constitution-hall-state-historic-site', 'weird-history', 39.04541, -95.39468, 'Lecompton', 'KS', 'This 1850s building stood at the center of territorial political battles over slavery and Kansas statehood. The surviving wooden hall provides a direct physical setting for the constitutional struggle that helped push the country toward civil war.', 'open', 'https://www.kansashistory.gov/constitution_hall', 'America/Chicago'),
  ('Shawnee Indian Mission Historic Site', 'shawnee-indian-mission-historic-site', 'weird-history', 39.03305, -94.62474, 'Fairway', 'KS', 'Three surviving buildings interpret the mission school where Shawnee, Delaware, and other Native children were educated under 19th-century federal assimilation policies. The site is historically important precisely because the story includes forced cultural change as well as local settlement history.', 'open', 'https://fairwaykansas.org/', 'America/Chicago'),
  ('Coronado Heights', 'coronado-heights', 'roadside-oddities', 38.61281, -97.70311, 'Lindsborg', 'KS', 'A WPA-era stone ''castle'' crowns a hill traditionally associated with the route of Francisco Vásquez de Coronado''s expedition. The historical connection is interpretive rather than a preserved expedition structure, but the isolated stone lookout is a distinctive roadside landmark.', 'open', 'https://www.visitlindsborg.com/', 'America/Chicago'),
  ('Johnny Kaw Statue', 'johnny-kaw-statue', 'folklore', 39.18013, -96.57367, 'Manhattan', 'KS', 'The giant green Johnny Kaw figure represents a fictional Kansas folk hero invented in the 1950s as a regional answer to Paul Bunyan. His exaggerated legends involve shaping Kansas geography, fighting giant creatures, and performing impossible farm feats.', 'open', 'https://www.mhkprd.com/', 'America/Chicago'),
  ('Goodnow House State Historic Site', 'goodnow-house-state-historic-site', 'weird-history', 39.19282, -96.59551, 'Manhattan', 'KS', 'The stone home of Isaac and Ellen Goodnow preserves the domestic world of influential Free-State settlers and founders of Kansas educational institutions. Its small scale and original setting make territorial-era political history unusually personal.', 'open', 'https://www.kansashistory.gov/goodnow_house', 'America/Chicago'),
  ('K-State Insect Zoo', 'k-state-insect-zoo', 'museums', 39.19517, -96.58449, 'Manhattan', 'KS', 'Kansas State University keeps live insects, arachnids, and other arthropods in a converted dairy barn beside its gardens. The collection turns creatures people usually avoid into a close-range museum experience with living specimens rather than pinned displays alone.', 'open', 'https://www.k-state.edu/butterfly/insect-zoo/', 'America/Chicago'),
  ('Eisenhower Presidential Library, Museum and Boyhood Home', 'eisenhower-presidential-library-museum-and-boyhood-home', 'weird-history', 38.91243, -97.21279, 'Abilene', 'KS', 'The complex combines Dwight D. Eisenhower''s boyhood home with his presidential museum, library, and final resting place. The contrast between a modest Kansas home and a career that reached Supreme Allied Commander and the presidency gives the site unusual narrative scale.', 'open', 'https://www.eisenhowerlibrary.gov/', 'America/Chicago'),
  ('World''s Largest Belt Buckle', 'worlds-largest-belt-buckle', 'roadside-oddities', 38.92017, -97.22884, 'Abilene', 'KS', 'A nearly 20-foot-wide steel belt buckle stands in Eisenhower Park and includes stairs that let visitors pose as if they are wearing it. The sculpture deliberately pushes Abilene''s cattle-town identity into modern roadside-superlative territory.', 'open', 'https://www.abilenekansas.org/', 'America/Chicago'),
  ('Greyhound Hall of Fame', 'greyhound-hall-of-fame', 'museums', 38.91176, -97.21437, 'Abilene', 'KS', 'This museum documents greyhound racing, breeding, famous dogs, trophies, and the culture surrounding the sport. Its single-subject focus is unusually specific, and retired greyhounds are often part of the visitor experience.', 'open', 'https://www.greyhoundhalloffame.com/', 'America/Chicago'),
  ('Old Abilene Town', 'old-abilene-town', 'weird-history', 38.91077, -97.21353, 'Abilene', 'KS', 'A recreated and preserved western townscape interprets Abilene''s cattle-drive era with period buildings, performances, and cowboy history. The site embraces the theatrical mythology of the Old West while remaining tied to the actual railhead town that made Abilene famous.', 'limited', 'https://www.oldabilenetown.com/', 'America/Chicago'),
  ('Museum of Independent Telephony', 'museum-of-independent-telephony', 'museums', 38.91126, -97.20856, 'Abilene', 'KS', 'The museum traces the independent telephone industry through switchboards, early handsets, equipment, and communications technology. It is a narrowly focused collection of obsolete machines that most travelers rarely encounter outside technical archives.', 'limited', 'https://www.dickinsoncountyhistoricalsociety.com/', 'America/Chicago'),
  ('World''s Largest ''I Like Ike'' Button', 'worlds-largest-i-like-ike-button', 'roadside-oddities', 38.91912, -97.2151, 'Abilene', 'KS', 'A six-foot convex campaign button recreates the iconic ''I Like Ike'' slogan at Little Ike Park. The oversized political object turns a 1950s presidential campaign symbol into a modern roadside photo stop.', 'open', 'https://www.abilenekansas.org/plan-your-visit/experience-art-culture/worlds-largest-i-like-ike-button', 'America/Chicago'),
  ('Home on the Range Cabin', 'home-on-the-range-cabin', 'weird-history', 39.88939, -98.94717, 'Athol', 'KS', 'A preserved log cabin stands near the place where Dr. Brewster Higley wrote the poem that became ''Home on the Range.'' The isolated prairie setting helps explain why the landscape itself became central to one of the best-known songs associated with the American West.', 'limited', 'https://www.travelks.com/', 'America/Chicago'),
  ('Twisted Oz Motorcycle Museum', 'twisted-oz-motorcycle-museum', 'museums', 37.67805, -96.98544, 'Augusta', 'KS', 'A free museum displays dozens of vintage and unusual motorcycles in a compact collection outside Wichita. The machines span different eras and styles, making it a strong mechanical-curiosity stop even for travelers who are not dedicated motorcycle enthusiasts.', 'open', 'https://www.twistedoz.com/', 'America/Chicago'),
  ('Field Station: Dinosaurs', 'field-station-dinosaurs', 'roadside-oddities', 37.58082, -97.24699, 'Derby', 'KS', 'A large outdoor attraction fills a Kansas landscape with life-size animatronic dinosaurs, fossil activities, shows, and dinosaur-themed mini golf. It is intentionally theatrical rather than a fossil museum, which gives it the feel of a modern roadside dinosaur park.', 'limited', 'https://kansasdinos.com/', 'America/Chicago'),
  ('Big Spur', 'big-spur', 'roadside-oddities', 38.93537, -97.21453, 'Abilene', 'KS', 'A 28-foot steel spur forms an arch outside a western-wear business on Abilene''s north side. It once held a Guinness record as the world''s largest spur and remains a conspicuous monument to the town''s cowboy identity.', 'open', 'https://www.abilenekansas.org/things-to-do/big-spur', 'America/Chicago'),
  ('Parker Carousel at the Dickinson County Heritage Center', 'parker-carousel-at-the-dickinson-county-heritage-center', 'weird-history', 38.9115, -97.2081, 'Abilene', 'KS', 'This hand-carved C.W. Parker carousel dates to around the turn of the 20th century and survives in operating condition at the heritage center. The ornate wooden horses and portable amusement machinery connect Abilene with a once-major Kansas carousel manufacturer.', 'limited', 'https://www.dickinsoncountyhistoricalsociety.com/', 'America/Chicago')
on conflict (slug) do update set
  name          = excluded.name,
  category      = excluded.category,
  city          = excluded.city,
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  timezone      = excluded.timezone;
